#include <iostream>
#include <string>
#include <vector>

int main() {
    int am;
    std::string zad;
    std::cin >> am >> zad;
    std::string s = zad;
    std::string skobki = "_";
    int strIndex = -1;
    int length = s.length();

    for (int i = 0; i < length; i++) {
        char c = s[i];
        if (c == '(') {
            strIndex = i;
        } else if (c == ')') {
            skobki += s.substr(strIndex + 1, i - strIndex - 1) + "_";
            s = s.substr(0, strIndex) + "_" + s.substr(i + 1);
            length = s.length();
            i = strIndex - 1;
            strIndex = -1;
        }
    }

    std::vector<std::string> parts;
    size_t start = 0, end;
    while ((end = skobki.find('_', start)) != std::string::npos) {
        parts.push_back(skobki.substr(start, end - start));
        start = end + 1;
    }
    if (start < skobki.size()) {
        parts.push_back(skobki.substr(start));
    }

    int count = 0;
    for (const auto& part : parts) {
        if (!part.empty()) {
            count++;
        }
    }

    std::vector<std::string> segments;
    start = 0;
    while ((end = s.find('_', start)) != std::string::npos) {
        segments.push_back(s.substr(start, end - start));
        start = end + 1;
    }
    if (start < s.size()) {
        segments.push_back(s.substr(start));
    }

    int maxLen = 0;
    for (const auto& segment : segments) {
        if (segment.length() > maxLen) {
            maxLen = segment.length();
        }
    }

    std::cout << maxLen << " " << count << std::endl;
    return 0;
}
